<?php declare(strict_types=1); namespace Annam; $title='Daily menus'; $subtitle=(new \DateTimeImmutable($date))->format('l, j F Y').' · '.$slot['label']; ?>
<nav class="php-tabs" aria-label="Meal"><?php foreach ($slots as $s): ?><a class="<?= $slotId===$s['id']?'selected':'' ?>" href="?slot_id=<?= e($s['id']) ?>&amp;date=<?= e($date) ?>"><?= e($s['label']) ?></a><?php endforeach; ?></nav>
<div class="php-date-bar"><form method="get"><input type="hidden" name="slot_id" value="<?= e($slotId) ?>"><label>Menu date <input type="date" name="date" value="<?= e($date) ?>" required></label><button class="o-btn" type="submit">View menu</button></form><nav class="php-tabs"><?php foreach ([date('Y-m-d')=>'Today',date('Y-m-d',strtotime('+1 day'))=>'Tomorrow'] as $day=>$label): ?><a class="<?= $date===$day?'selected':'' ?>" href="?slot_id=<?= e($slotId) ?>&amp;date=<?= e($day) ?>"><?= e($label) ?></a><?php endforeach; ?></nav></div>
<p class="o-muted">Choose the dishes for this date and meal. Saving does not change another date, delete products or reset stock.</p><form method="post"><?= csrf() ?><input type="hidden" name="slot_id" value="<?= e($slotId) ?>"><input type="hidden" name="date" value="<?= e($date) ?>"><input type="hidden" name="revision" value="<?= e($revision) ?>"><div class="o-card php-menu-pick-grid">
<?php foreach ($items as $item): if (!$item['active']) continue; ?><label class="o-check php-menu-pick"><input type="checkbox" name="items[]" value="<?= e($item['id']) ?>" <?= in_array($item['id'],$selected)?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><?php if ($item['image']): ?><img src="<?= e(image_url($item['image'])) ?>" width="56" height="56" alt="" loading="lazy"><?php endif; ?><span class="o-toggle-copy"><b><?= e($item['name']) ?></b><small><?= money($item['price']) ?></small></span></label><?php endforeach; ?></div><div class="o-form-bar"><button class="o-btn o-btn-primary" type="submit">Save <?= e($slot['label']) ?> menu →</button></div></form>
